/**
 * Buying inside the Android app.
 *
 * Google Play must be the seller here: their rules do not allow anything
 * else for digital goods, and breaking that can get the app removed. So the
 * same plan is bought two ways — Paddle's overlay on the web, Play's sheet
 * in the app — and both end in the same place, with the server deciding what
 * was actually bought.
 *
 * Nothing in this file decides that anybody has paid. Play hands back a
 * token; the server asks Google what the token is worth. A token this file
 * invented would buy nothing.
 */
import { shellPlatform } from '@/lib/platform/detect.js';

/** The native plugin, as the web layer sees it. */
interface PlayBilling {
  /** Whether this device and country can buy a subscription at all. */
  isAvailable(): Promise<{ available: boolean }>;
  /**
   * Opens Play's purchase sheet. Resolves with the token when it worked,
   * and with `cancelled` when the person backed out, which is not an error.
   */
  purchase(options: { productId: string; accountId: string }): Promise<{
    cancelled: boolean;
    purchaseToken?: string;
  }>;
  /** Every subscription token this device holds. */
  purchases(): Promise<{ purchaseTokens: string[] }>;
}

let plugin: Promise<PlayBilling> | undefined;

/**
 * Registered on first use, and only then is Capacitor's bridge loaded, so a
 * browser that never buys through Play never downloads it. Every entry point
 * below checks the platform first.
 */
function billing(): Promise<PlayBilling> {
  plugin ??= import('@capacitor/core').then(({ registerPlugin }) => registerPlugin<PlayBilling>('Billing'));
  return plugin;
}

/** Whether this build is the Android app, where Play is the only seller. */
export function onAndroid(): boolean {
  return shellPlatform() === 'android';
}

/**
 * Whether this build is the iPhone app. Apple's rules (App Store Review
 * Guideline 3.1.1) allow only its own in-app purchase for digital goods, and
 * the app has none yet, so nothing in it may sell, link to a checkout or
 * unlock Pro with a code of ours. The server's `selling.ios` switch is not
 * enough on its own: there is no StoreKit purchase for it to switch on.
 */
export function onIOS(): boolean {
  return shellPlatform() === 'ios';
}

/** What a purchase attempt ended as, in the same words the web one uses. */
export type Outcome = { kind: 'bought'; purchaseToken: string } | { kind: 'closed' };

/**
 * Opens Play's sheet for one plan. The account travels with the purchase and
 * comes back to the server on Google's side of it; it is the only link
 * between a payment and a person, which is why the server refuses a purchase
 * that carries somebody else's.
 */
export async function buyOnPlay(plan: string, accountId: string): Promise<Outcome> {
  const result = await (await billing()).purchase({ productId: plan, accountId });
  if (result.cancelled || result.purchaseToken === undefined) return { kind: 'closed' };
  return { kind: 'bought', purchaseToken: result.purchaseToken };
}

/**
 * The tokens this device already holds.
 *
 * This is what makes a reinstall, a new phone, or a purchase that finished
 * while the app was closed work: each token goes to the server, which asks
 * Google what it is worth. A device with nothing to restore answers with an
 * empty list, which is the ordinary case and not a failure.
 */
export async function heldPurchases(): Promise<string[]> {
  if (!onAndroid()) return [];
  try {
    const { purchaseTokens } = await (await billing()).purchases();
    return purchaseTokens;
  } catch {
    // Play services missing, or the sheet unavailable in this country.
    // Nothing to restore is the right answer either way.
    return [];
  }
}

/** Whether Play can sell on this device at all. */
export async function playCanSell(): Promise<boolean> {
  if (!onAndroid()) return false;
  try {
    const { available } = await (await billing()).isAvailable();
    return available;
  } catch {
    return false;
  }
}
